import ast
import operator
from flask import Flask, request, jsonify

app = Flask(__name__)

# Safe arithmetic evaluation using AST
_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


def _eval_node(node):
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
            return node.value
        raise ValueError("Invalid constant")
    if isinstance(node, ast.BinOp):
        op_type = type(node.op)
        if op_type not in _BIN_OPS:
            raise ValueError("Unsupported operator")
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        # Guard against huge exponents
        if op_type is ast.Pow and (abs(right) > 1000 or abs(left) > 1e6):
            raise ValueError("Exponent too large")
        return _BIN_OPS[op_type](left, right)
    if isinstance(node, ast.UnaryOp):
        op_type = type(node.op)
        if op_type not in _UNARY_OPS:
            raise ValueError("Unsupported unary operator")
        return _UNARY_OPS[op_type](_eval_node(node.operand))
    raise ValueError("Unsupported expression")


def evaluate(expression):
    if not isinstance(expression, str):
        raise ValueError("Expression must be a string")
    if len(expression) > 1000:
        raise ValueError("Expression too long")
    tree = ast.parse(expression, mode="eval")
    return _eval_node(tree)


def _format_result(value):
    if isinstance(value, float):
        if value.is_integer():
            return str(int(value))
        return repr(value)
    return str(value)


@app.route("/calculator", methods=["POST"])
def calculator():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid JSON body"}), 400
    expression = data.get("expression")
    if expression is None:
        return jsonify({"error": "Missing 'expression' field"}), 400
    try:
        result = evaluate(expression)
    except (ValueError, SyntaxError, ZeroDivisionError, TypeError, OverflowError):
        return jsonify({"error": "Invalid input"}), 400
    return jsonify({"result": _format_result(result)}), 200


@app.route("/", methods=["GET"])
def index():
    return (
        "<html><body><h1>MyCalculator</h1>"
        "<p>POST JSON {\"expression\": \"1 + 2*3\"} to /calculator</p>"
        "</body></html>"
    )


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
